node <<'EOF'
const fs=require('fs');
const me=process.pid;
const dirs=fs.readdirSync('/proc').filter(d=>/^[0-9]+$/.test(d));
const found=[];
for(const d of dirs){
  try{
    const cmd=fs.readFileSync('/proc/'+d+'/cmdline').toString().replace(/\0/g,' ').trim();
    if(cmd.includes('src/server.js') || (cmd.includes('npm') && cmd.includes('start'))){
      found.push({pid:d,cmd});
    }
  }catch(e){}
}
