for(const f of found){
  if(Number(f.pid)===me) continue;
  try{ process.kill(Number(f.pid),'SIGKILL'); console.log('killed',f.pid); }
  catch(e){ console.log('could not kill',f.pid,e.code); }
}
EOF
sleep 3
(curl -s -o /dev/null -w "port: %{http_code}\n" --max-time 3 http://127.0.0.1:4000/ 2>/dev/null || echo "port: not listening")

