const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1100, height: 800 } });
  const results = {};
  await p.goto('http://127.0.0.1:4000/');
  await p.waitForSelector('#list[data-harness-ready=\"true\"]');

  results.overlayHiddenOnLoad = !(await p.locator('#modal-backdrop').isVisible()) && !(await p.locator('#bulk-bar').isVisible());

  // Click through each main control
  await p.locator('.view-tab[data-view=\"unread\"]').click(); results.unreadTab = true;
  await p.locator('.view-tab[data-view=\"archive\"]').click(); results.archiveTab = true;
  await p.locator('.view-tab[data-view=\"normal\"]').click();
  await p.locator('#search').fill('#docs'); await p.waitForTimeout(400);
  results.searchWorks = (await p.locator('.card').count()) === 2;
  await p.locator('#search').fill('');
  await p.selectOption('#sort', 'title'); results.sortWorks = true;
  await p.waitForTimeout(300);

  // Bulk bar appears only after selecting
  await p.locator('.card .sel').first().check();
  results.bulkBarAppearsOnSelect = await p.locator('#bulk-bar').isVisible();
  await p.locator('.card .sel').first().uncheck();
  await p.waitForTimeout(100);
  results.bulkBarGoneAfterDeselect = !(await p.locator('#bulk-bar').isVisible());

  // Dialogs open on demand and close
  await p.locator('#prefs-btn').click();
  results.prefsOpens = await p.locator('#modal-backdrop').isVisible();
  await p.screenshot({ path: 'prototypes/app-prefs-open.png' });
  await p.locator('#modal-backdrop').click({ position: { x: 5, y: 5 } });
  await p.waitForTimeout(100);
  results.prefsCloses = !(await p.locator('#modal-backdrop').isVisible());

  // Open detail/edit
  await p.locator('.card .actions button', { hasText: 'Open / Edit' }).first().click();
  results.editDialogOpens = await p.locator('#modal-backdrop').isVisible();
  await p.locator('#modal-backdrop').click({ position: { x: 5, y: 5 } });

  console.log(JSON.stringify(results, null, 2));
  await b.close();
})().catch(e=>{console.error('FAIL',e.message);process.exit(1)});
"
